# CREATE
POST /articles
Content-Type: application/json
{ "title": "Hello", "body": "World" }
→ 201 Created  { "id": 7, "title": "Hello" }

# READ (list)
GET /articles
→ 200 OK  [{ "id": 1 }, { "id": 7 }]

# READ (single)
GET /articles/7
→ 200 OK  { "id": 7, "title": "Hello", "body": "World" }

# UPDATE (replace completely)
PUT /articles/7
{ "title": "Updated title", "body": "Updated body" }
→ 200 OK  { "id": 7, "title": "Updated title", "body": "Updated body" }

# UPDATE (partial change — only what you send changes)
PATCH /articles/7
{ "title": "New title only" }
→ 200 OK  { "id": 7, "title": "New title only", "body": "World" }

# DELETE
DELETE /articles/7
→ 204 No Content  (no body)
